  methods: {
    success_info(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        // Change color to indicate an error
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
      this.addsubDialog = false;
      this.createAssetDialog = false;
      this.deletetagDialog = false;
      this.editTagDialog = false;
      this.activateDeactivate = false;
      this.fetch_asset_tags();
    },
    error_info(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        // Change color to indicate an error
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
    },
    create_tags() {
      this.componentCheck = 1;
      this.createAssetDialog = true;
    },
    async fetch_asset_tags() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_delete_tags, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "LIST_TAGS"
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_delete_tags);
        this.tableLoading = false;
        this.tagDisplay = true;
        if (response.Status == "SUCCESS") {
          this.existingRecords = response.data;
          this.tagRecords = response.data;
          this.tagRecords.sort((a, b) => {
            return a.tag_prefix.localeCompare(b.tag_prefix);
          });
        } else {
          this.tableLoading = false;
          this.tagRecords = [];
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            // Change color to indicate an error
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          // Change color to indicate an error
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    add_sub_tags(item) {
      this.rowInfo = item;
      this.addSubTagDialog = true;
      this.componentCheck = 2;
    },
    activate_deactivate_dialog(item) {
