      this.rowInfo = item;
      this.componentCheck = 4;
      this.editTagDialog = true;
    },
    delete_dialog(value) {
      this.deletetagDialog = true;
      this.componentCheck = 3;
      this.rowInfo = value;
      this.deleteItem = value;
    }
